[Theory]
[InlineData("A-1", 2)]
[InlineData("B-7", 1)]
public void QuoteIsPinned(string sku, int qty)
{
    var got = LegacyPricing.Quote(sku, qty).ToCanonicalJson();
    var path = Path.Combine(TestData, $"quote_{sku}.json");
    if (Environment.GetEnvironmentVariable("UPDATE_GOLDEN") is not null) File.WriteAllText(path, got);
    Assert.Equal(File.ReadAllText(path), got);   // xUnit prints the diff
}
